arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg-base: #0F0F0F;
  --bg-surface: #1E1E2E;
  --bg-elevated: #28283D;
  --bg-hover: #32324A;
  --text-primary: #FFFFFF;
  --text-secondary: #A1A1AA;
  --text-tertiary: #71717A;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1E4BD8;
  --color-green: #089981;
  --color-green-bg: rgba(8, 153, 129, 0.15);
  --color-red: #F7525F;
  --color-red-bg: rgba(247, 82, 95, 0.15);
  --border-color: #27273A;
  --border-light: #3F3F5A;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -1px rgba(0, 0, 0, 0.3);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
}
h1 { font-size: 2.5rem; margin-bottom: 1rem; }
h2 { font-size: 1.5rem; margin-bottom: 1rem; }
h3 { font-size: 1.25rem; margin-bottom: 0.75rem; }
.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-secondary { color: var(--text-secondary); }
.text-positive { color: var(--color-green); }
.text-negative { color: var(--color-red); }

/* Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-2 { gap: 0.5rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }
.grid { display: grid; }

/* Header */
.site-header {
  height: 64px;
  background-color: var(--bg-base);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
}
.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-icon {
  width: 24px;
  height: 24px;
  background: linear-gradient(135deg, var(--accent-blue), #5E8CFF);
  border-radius: 4px;
}
.main-nav {
  display: flex;
  gap: 24px;
}
.main-nav a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s;
}
.main-nav a:hover, .main-nav a.active {
  color: var(--text-primary);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all 0.2s;
}
.btn-primary {
  background-color: var(--accent-blue);
  color: white;
}
.btn-primary:hover {
  background-color: var(--accent-blue-hover);
}
.btn-secondary {
  background-color: var(--bg-surface);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}
.btn-secondary:hover {
  background-color: var(--bg-hover);
  border-color: var(--border-light);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 16px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 16px;
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }
.tab {
  padding: 8px 0;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
}
.tab:hover {
  color: var(--text-primary);
}
.tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Tables */
.table-container {
  overflow-x: auto;
}
table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}
th {
  padding: 12px 16px;
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
}
td {
  padding: 12px 16px;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--border-color);
}
tr:last-child td {
  border-bottom: none;
}
tr:hover td {
  background-color: var(--bg-surface);
}

/* Cards */
.card {
  background-color: var(--bg-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  padding: 16px;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-positive {
  background-color: var(--color-green-bg);
  color: var(--color-green);
}
.badge-negative {
  background-color: var(--color-red-bg);
  color: var(--color-red);
}
.badge-neutral {
  background-color: var(--bg-elevated);
  color: var(--text-secondary);
}

/* Footer */
.site-footer {
  margin-top: auto;
  background-color: var(--bg-base);
  border-top: 1px solid var(--border-color);
  padding: 48px 0 24px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 32px;
  margin-bottom: 48px;
}
.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 16px;
}
.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.footer-col a {
  font-size: 0.875rem;
  color: var(--text-secondary);
}
.footer-col a:hover {
  color: var(--text-primary);
}
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  font-size: 0.75rem;
  color: var(--text-secondary);
}

/* Utilities */
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.mt-4 { margin-top: 1rem; }
.mt-8 { margin-top: 2rem; }
.p-4 { padding: 1rem; }
.w-full { width: 100%; }

/* Main content wrapper */
.main-content {
  flex: 1;
}

/* Mini sparklines */
.sparkline {
  height: 24px;
  width: 60px;
  display: inline-block;
  background-repeat: no-repeat;
  background-size: 100% 100%;
}
.sparkline-green {
  background-image: url('data:image/svg+xml;utf8,<svg preserveAspectRatio="none" viewBox="0 0 100 20" xmlns="http://www.w3.org/2000/svg"><path d="M0,20 Q10,15 20,18 T40,10 T60,12 T80,5 T100,2" fill="none" stroke="%23089981" stroke-width="2"/></svg>');
}
.sparkline-red {
  background-image: url('data:image/svg+xml;utf8,<svg preserveAspectRatio="none" viewBox="0 0 100 20" xmlns="http://www.w3.org/2000/svg"><path d="M0,2 Q10,5 20,3 T40,10 T60,8 T80,15 T100,18" fill="none" stroke="%23F7525F" stroke-width="2"/></svg>');
}

/* Hero Section */
.hero {
  padding: 80px 0;
  text-align: center;
}
.hero h1 {
  font-size: 4rem;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}
.hero p {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
}

/* Market Summary Bar */
.market-summary-bar {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding: 12px 24px;
  background-color: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  scrollbar-width: none;
}
.market-summary-bar::-webkit-scrollbar { display: none; }
.summary-item {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  font-size: 0.875rem;
}
.summary-name {
  font-weight: 500;
}
